15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
25	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
26	    @Mapping(target = "locality", expression = "java(locality(owner))")
27	    OwnerDto toOwnerDto(Owner owner);
28	
29	    Owner toOwner(OwnerDto ownerDto);
30	
31	    /** Format an owner's name as 'LastName, FirstName' for display. */
32	    default String displayName(Owner owner) {
33	        return owner.getLastName() + ", " + owner.getFirstName();
34	    }
35	
36	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot. */
37	    default String initials(Owner owner) {
38	        return initial(owner.getFirstName()) + initial(owner.getLastName());
39	    }
40	
41	    private static String initial(String name) {
42	        return Character.toUpperCase(name.charAt(0)) + ".";
43	    }
44	
45	    /** The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
46	     * last two digits of the registrationDate year. */
47	    default String membershipNumber(Owner owner) {
48	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
49	            return null;
50	        }
51	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
52	    }
53	
54	    /** The owner's membership tier: 'GOLD' when the owner's household has 3 or more members,
55	     * otherwise 'SILVER' when namesakeCount is 0 and an email is present, otherwise 'BRONZE'. */
56	    default String membershipTier(Owner owner) {
57	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
58	            return "GOLD";
59	        }
60	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
61	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
62	        return unique && hasEmail ? "SILVER" : "BRONZE";
63	    }
64	
65	    /** The owner's canonical region, derived from the city via the pinned city-to-region table,
66	     * or 'UNKNOWN' when the city is not in the table. */
67	    default String locality(Owner owner) {
68	        return Locality.regionFor(owner.getCity());
69	    }
70	
71	    @Mapping(target = "id", ignore = true)
72	    @Mapping(target = "pets", ignore = true)
73	    @Mapping(target = "customerCode", ignore = true)
74	    @Mapping(target = "householdId", ignore = true)
75	    @Mapping(target = "namesakeCount", ignore = true)
76	    @Mapping(target = "householdSize", ignore = true)
77	    @Mapping(target = "bulkSignupWarning", ignore = true)
78	    Owner toOwner(OwnerFieldsDto ownerDto);
79	
80	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
81	
82	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
83	
84	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
85	        OwnerPageDto ownerPageDto = new OwnerPageDto();
86	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
87	        ownerPageDto.setPage(ownerPage.getNumber());
88	        ownerPageDto.setSize(ownerPage.getSize());
89	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
90	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
91	        return ownerPageDto;
92	    }
93	}
