3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Records how many existing owners already share the built owner's first and last name,
11	 * compared case-insensitively. Runs after the owner is built but before it is saved, so the
12	 * count reflects the owners that existed before this create, and mutates the built
13	 * {@link Owner} in place.
14	 */
15	public class AssignOwnerNamesakeCount {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String firstName = canonical(owner.getFirstName());
19	        String lastName = canonical(owner.getLastName());
20	        int namesakes = 0;
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (firstName.equals(canonical(existing.getFirstName()))
23	                    && lastName.equals(canonical(existing.getLastName()))) {
24	                namesakes++;
25	            }
26	        }
27	        owner.setNamesakeCount(namesakes);
28	    }
29	
30	    private static String canonical(String value) {
31	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
32	    }
33	}
